script:
frappe.ui.form.on('Quran Receipt', {
    // 1. إعداد الفلتر أول ما الفورم يفتح (عشان حقل الدفتر يعرض المفتوح بس)
    setup: function(frm) {
        frm.set_query('receipt_book', function() {
            return {
                filters: {
                    status: 'مفتوح'
                }
            };
        });
    },

    onload: function(frm) {
        // بنشتغل بس لو إيصال جديد
        if (frm.is_new()) {

            // جلب Academic Year من Settings
            if (!frm.doc.academic_year) {
                frappe.db.get_single_value('Quran Settings', 'academic_year')
                    .then(function(val) {
                        if (val) {
                            frm.set_value('academic_year', val);
                        }
                    });
            }

            // جلب Current Period (الأشهر المستهدفة) من Settings
            if (!frm.doc.targeted_months) {
                frappe.db.get_single_value('Quran Settings', 'current_period')
                    .then(function(val) {
                        if (val) {
                            frm.set_value('targeted_months', val);
                        }
                    });
            }

            // جلب الدفتر المفتوح تلقائياً
            if (!frm.doc.receipt_book) {
                frappe.db.get_value('Quran Receipt Book', {status: 'مفتوح'}, 'name').then(r => {
                    if (r.message && r.message.name) {
                        frm.set_value('receipt_book', r.message.name);
                    } else {
                        frappe.msgprint({
                            title: 'تنبيه',
                            indicator: 'orange',
                            message: 'لا يوجد دفتر إيصالات مفتوح حالياً. يرجى فتح دفتر جديد أولاً قبل تسجيل الإيصالات.'
                        });
                    }
                });
            }
        }
    },

    // 2. التحقق من الدفتر المختار (عشان نمنع أي محاولة لاختيار دفتر مغلق)
    receipt_book: function(frm) {
        if (frm.doc.receipt_book) {
            // بنجيب حالة الدفتر اللي اختاره
            frappe.db.get_value('Quran Receipt Book', frm.doc.receipt_book, 'status').then(r => {
                if (r.message && r.message.status === 'مغلق') {
                    frappe.msgprint({
                        title: 'خطأ',
                        indicator: 'red',
                        message: 'لا يمكن اختيار دفتر مغلق. يجب استخدام دفتر مفتوح فقط.'
                    });
                    frm.set_value('receipt_book', ''); // بنمسح الاختيار
                } else {
                    // لو مفتوح، بنكمل ونطلب رقم الإيصال
                    if (frm.is_new()) {
                        get_next_receipt_number(frm);
                    }
                }
            });
        }
    }
});

// الدالة الخاصة بجلب رقم الإيصال التالي
function get_next_receipt_number(frm) {
    frappe.db.get_doc('Quran Receipt Book', frm.doc.receipt_book).then(book => {
        let start_no = book.start_receipt_no || 1;

        frappe.db.get_list('Quran Receipt', {
            filters: { receipt_book: frm.doc.receipt_book },
            fields: ['paper_receipt_no'],
            limit: 0
        }).then(res => {
            let next_no = start_no;

            if (res && res.length > 0) {
                let numbers = res.map(r => parseInt(r.paper_receipt_no)).filter(n => !isNaN(n));
                if (numbers.length > 0) {
                    let max_no = Math.max(...numbers); 
                    if (max_no >= next_no) {
                        next_no = max_no + 1;
                    }
                }
            }

            frm.set_value('paper_receipt_no', next_no);
        });
    });
}

frappe.ui.form.on('Student Group', {
    onload: function(frm) {
        // بس لو إيصال جديد
        if (frm.is_new()) {

            // جلب Academic Year من Settings
            if (!frm.doc.academic_year) {
                frappe.db.get_single_value('Quran Settings', 'academic_year')
                    .then(function(val) {
                        if (val) {
                            frm.set_value('academic_year', val);
                        }
                    });
            }

        }
    }
});

frappe.ui.form.on('Quran Receipt', {
	student: function(frm) {
	    if (frm.doc.student) {
	        frappe.db.get_doc('Student', frm.doc.student).then(student => {

	            let prev_bal = student.custom_previous_balance || 0; 
	            let curr_rem = student.custom_current_remaining || 0;
	            frm.set_value('previous_balance', prev_bal);
	            frm.set_value('current_remaining', curr_rem);

	            let total = prev_bal + curr_rem;
	            frm.set_value('total_outstanding', total);
	            frm.set_value('paid_amount', 0);
	            frm.set_value('remaining_balance', total);




	        });
	    }
	},
	paid_amount: function(frm) {
	    calculate_remaining(frm);
	},


	btn_60: function(frm) {
	    frm.set_value('paid_amount', 60);
	},
	btn_120: function(frm) {
	    frm.set_value('paid_amount', 120);
	},
	btn_180: function(frm) {
	    frm.set_value('paid_amount', 180);
	},
	btn_full: function(frm) {
	    frm.set_value('paid_amount', frm.doc.total_outstanding);
	},
});



function calculate_remaining(frm) {
    let total = frm.doc.total_outstanding || 0;
    let paid = frm.doc.paid_amount || 0;
    let remaining = total - paid;

    if (remaining < 0) {
        remaining = 0;
        frappe.show_alert({
            message: __('Paid amount bigger than what needed!!'),
            indicator: 'orange'
        });

    }

    frm.set_value('remaining_balance', remaining)
}

frappe.ui.form.on('Quran Receipt Book', {
    onload: function(frm) {
        if (frm.is_new()) {
            if (frm.fields_dict.receipts_html) {
                frm.fields_dict.receipts_html.$wrapper.empty();
            }

            frappe.db.get_value('Quran Receipt Book', {status: 'مفتوح'}, 'name').then(r => {
                if (r.message && r.message.name) {
                    frappe.msgprint({
                        title: 'تنبيه هام',
                        indicator: 'red',
                        message: `يوجد دفتر مفتوح بالفعل (<b>${r.message.name}</b>).<br>يجب إغلاقه أولاً قبل إنشاء دفتر جديد.`
                    });
                    frm.disable_save();
                }
            });
        }
    },

    refresh: function(frm) {
        if (!frm.is_new()) {
            render_html_table(frm);
        }

        // 🌟 التعديل هنا: التحكم في زرار "New Receipt" بناءً على حالة الدفتر
        if (frm.fields_dict.new_receipt && frm.fields_dict.new_receipt.$input) {
            let btn = frm.fields_dict.new_receipt.$input;

            if (frm.doc.status === 'مغلق') {
                // لو الدفتر مغلق: نعطل الزرار ونخليه باهت
                btn.prop('disabled', true);
                btn.css({'opacity': '0.5', 'cursor': 'not-allowed'});
            } else {
                // لو الدفتر مفتوح: نشغل الزرار ونرجع لونه الطبيعي
                btn.prop('disabled', false);
                btn.css({'opacity': '1', 'cursor': 'pointer'});

                btn.off('click').on('click', function() {
                    if (frm.is_new()) {
                        frappe.msgprint('يجب حفظ الدفتر أولاً قبل تسجيل الإيصالات.');
                        return;
                    }
                    open_receipt_dialog(frm);
                });
            }
        }

        if (frappe.route_options && frappe.route_options.trigger_dialog) {
            open_receipt_dialog(frm);
            frappe.route_options.trigger_dialog = null; // نمسح العلامة عشان ميفضلش يفتح كل ما يعمل refresh
        }
    }
});

// ==========================================
// 1. دالة رسم الجدول (HTML)
// ==========================================
function render_html_table(frm) {
    let html_field = frm.fields_dict.receipts_html.$wrapper;
    html_field.html('<div style="text-align:center; padding:20px;">جاري تحميل الإيصالات...</div>');

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Quran Receipt',
            filters: { receipt_book: frm.doc.name },
            fields: ['name', 'paper_receipt_no', 'student_name', 'payment_date', 'academic_year', 'paid_amount', 'remaining_balance'],
            order_by: 'paper_receipt_no desc',
            limit_page_length: 0
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                let rows = '';
                r.message.forEach((rec) => {
                    rows += `
                        <tr>
                            <td style="text-align:center; font-weight:bold;">${rec.paper_receipt_no}</td>
                            <td>${rec.student_name || 'غير محدد'}</td>
                            <td style="text-align:center;">${frappe.datetime.str_to_user(rec.payment_date)}</td>
                            <td style="text-align:center;">${rec.academic_year || ''}</td>
                            <td style="text-align:left;">${format_currency(rec.paid_amount)}</td>
                            <td style="text-align:left; color:#d9534f;">${format_currency(rec.remaining_balance)}</td>
                            <td style="text-align:center;">
                                <a href="/app/quran-receipt/${rec.name}" target="_blank" class="btn btn-xs btn-default">عرض</a>
                            </td>
                        </tr>
                    `;
                });

                let table_html = `
                    <div class="table-responsive" style="max-height: 400px; overflow-y: auto; border: 1px solid #d1d8dd; border-radius: 6px;">
                        <table class="table table-bordered table-hover" style="margin-bottom: 0;">
                            <thead style="background: #f4f5f7; position: sticky; top: 0; z-index: 1;">
                                <tr>
                                    <th style="text-align:center;">رقم الإيصال</th>
                                    <th>الطالب</th>
                                    <th style="text-align:center;">التاريخ</th>
                                    <th style="text-align:center;">العام الدراسي</th>
                                    <th>المدفوع</th>
                                    <th>المتبقي</th>
                                    <th style="text-align:center;">الإجراء</th>
                                </tr>
                            </thead>
                            <tbody>${rows}</tbody>
                        </table>
                    </div>
                `;
                html_field.html(table_html);
            } else {
                html_field.html('<div style="text-align:center; padding:20px; color:#888; border:1px dashed #ccc; border-radius:6px;">لا توجد إيصالات مسجلة في هذا الدفتر حتى الآن.</div>');
            }
        }
    });
}

// ==========================================
// 2. دالة فتح النافذة المنبثقة (Dialog) 
// ==========================================
function open_receipt_dialog(frm) {
    if (!frm.doc.start_receipt_no || frm.doc.start_receipt_no == 0) {
        frappe.msgprint('⚠️ يجب تحديد (رقم أول إيصال) في الدفتر أولاً قبل تسجيل الإيصالات.');
        return;
    }

    let d = new frappe.ui.Dialog({
        title: 'تسجيل إيصال جديد - ' + frm.doc.name,
        fields: [
            { fieldname: 'paper_receipt_no', label: 'رقم الإيصال الورقي', fieldtype: 'Data', reqd: 1 },
            { 
                fieldname: 'custom_student_code', 
                label: 'كود الطالب (القديم)', 
                fieldtype: 'Data', 
                reqd: 1,
                onchange: function() {
                    let code = d.get_value('custom_student_code');
                    if (code) {
                        frappe.db.get_value('Student', { custom_student_code: code }, ['name', 'student_name']).then(r => {
                            if (r.message) {
                                d.set_value('student', r.message.name); 
                                d.set_value('student_name', r.message.student_name); 
                            } else {
                                d.set_value('student', '');
                                d.set_value('student_name', '');
                                frappe.show_alert({message: 'لم يتم العثور على طالب بهذا الكود', indicator: 'red'});
                            }
                        });
                    } else {
                        d.set_value('student', '');
                        d.set_value('student_name', '');
                    }
                }
            },
            { fieldname: 'student_name', label: 'اسم الطالب', fieldtype: 'Data', read_only: 1 },
            { fieldname: 'student', fieldtype: 'Link', options: 'Student', hidden: 1 },
            { fieldname: 'payment_date', label: 'تاريخ السداد', fieldtype: 'Date', default: frappe.datetime.get_today(), reqd: 1 },
            { fieldname: 'academic_year', label: 'العام الدراسي', fieldtype: 'Link', options: 'Academic Year', reqd: 1 },
            { fieldtype: 'Column Break' },
            { 
                fieldname: 'targeted_months', 
                label: 'الفترة المستهدفة', 
                fieldtype: 'Select', 
                options: 'يناير، فبراير، مارس\nأبريل، مايو، يونيو\nيوليو، أغسطس، سبتمبر\nأكتوبر، نوفمبر، ديسمبر',
                reqd: 1 
            },
            { fieldname: 'is_late_entry', label: 'متأخرات؟ (Is Late Entry)', fieldtype: 'Check' },
            { fieldname: 'paid_amount', label: 'المبلغ المدفوع', fieldtype: 'Currency', reqd: 1 },
            { fieldname: 'quick_pay_html', fieldtype: 'HTML' }
        ],
        primary_action_label: 'حفظ وإضافة التالي',
        primary_action(values) {
            if (!values.student) {
                frappe.msgprint('الرجاء التأكد من كتابة كود طالب صحيح أولاً.');
                return;
            }

            frappe.call({
                method: 'frappe.client.insert',
                args: {
                    doc: {
                        doctype: 'Quran Receipt',
                        receipt_book: frm.doc.name,
                        paper_receipt_no: values.paper_receipt_no,
                        student: values.student,
                        student_name: values.student_name,
                        payment_date: values.payment_date,
                        academic_year: values.academic_year,
                        targeted_months: values.targeted_months,
                        is_late_entry: values.is_late_entry,
                        paid_amount: values.paid_amount
                    }
                },
                callback: function(r) {
                    if (!r.exc) {
                        // 🌟 التعديل هنا: ضفنا 2 عشان الإشعار يختفي في ثانيتين
                        frappe.show_alert({
                            message: `تم حفظ الإيصال بنجاح. المتبقي: ${r.message.remaining_balance || 0}`,
                            indicator: 'green'
                        }, 2);

                        // 1. تحديث الجدول في الخلفية
                        render_html_table(frm); 

                        // 2. تفريغ الحقول عشان نستعد للإيصال الجديد
                        d.set_value('custom_student_code', '');
                        d.set_value('student', '');
                        d.set_value('student_name', '');
                        d.set_value('paid_amount', '');
                        d.set_value('is_late_entry', 0);

                        // 3. جلب رقم الإيصال التالي فوراً
                        get_next_receipt_no(frm, d);

                        // 4. وضع المؤشر في أول خانة
                        setTimeout(() => {
                            d.fields_dict.custom_student_code.$input.focus();
                        }, 500);

                        frm.reload_doc(); 
                    }
                }
            });
        }
    });

    // إضافة زراير الدفع السريع
    let buttons_html = `
        <div style="display: flex; gap: 10px; margin-top: 10px;">
            <button class="btn btn-default btn-sm" id="btn_quick_60" style="flex: 1; font-weight: bold;">دفع 60</button>
            <button class="btn btn-default btn-sm" id="btn_quick_120" style="flex: 1; font-weight: bold;">دفع 120</button>
            <button class="btn btn-default btn-sm" id="btn_quick_180" style="flex: 1; font-weight: bold;">دفع 180</button>
        </div>
    `;
    d.fields_dict.quick_pay_html.$wrapper.html(buttons_html);

    d.fields_dict.quick_pay_html.$wrapper.find('#btn_quick_60').on('click', function() { d.set_value('paid_amount', 60); });
    d.fields_dict.quick_pay_html.$wrapper.find('#btn_quick_120').on('click', function() { d.set_value('paid_amount', 120); });
    d.fields_dict.quick_pay_html.$wrapper.find('#btn_quick_180').on('click', function() { d.set_value('paid_amount', 180); });

    // جلب الإعدادات
    Promise.all([
        frappe.db.get_single_value('Quran Settings', 'academic_year'),
        frappe.db.get_single_value('Quran Settings', 'current_period')
    ]).then(([academic_year, current_period]) => {
        if (academic_year) d.set_value('academic_year', academic_year);
        if (current_period) d.set_value('targeted_months', current_period); 
    });

    // دالة الترقيم التلقائي
    function get_next_receipt_no(frm, dialog) {
        frappe.db.get_list('Quran Receipt', {
            filters: { receipt_book: frm.doc.name },
            fields: ['paper_receipt_no'],
            limit: 0 
        }).then(res => {
            let next_no = frm.doc.start_receipt_no; 
            if (res && res.length > 0) {
                let numbers = res.map(r => parseInt(r.paper_receipt_no)).filter(n => !isNaN(n));
                if (numbers.length > 0) {
                    let max_no = Math.max(...numbers); 
                    if (max_no >= next_no) {
                        next_no = max_no + 1; 
                    }
                }
            }
            dialog.set_value('paper_receipt_no', next_no);
        });
    }

    get_next_receipt_no(frm, d);
    d.show();
}

frappe.ui.form.on('Student', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            render_custom_student_receipts(frm);
        }
    },

    // عشان الفلتر يشتغل لايف أول ما تختار العام الدراسي
    academic_year_filter: function(frm) {
        render_custom_student_receipts(frm);
    }
});

function render_custom_student_receipts(frm) {
    let html_field = frm.fields_dict.custom_student_receipts_html.$wrapper;
    if (!html_field) return; 

    html_field.html('<div style="text-align:center; padding:20px;">جاري تحميل الإيصالات...</div>');

    let filters = { student: frm.doc.name };

    // فلترة بالعام الدراسي لو متحدد
    if (frm.doc.academic_year_filter) {
        filters.academic_year = frm.doc.academic_year_filter;
    }

    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Quran Receipt',
            filters: filters,
            fields: ['name', 'receipt_book', 'paper_receipt_no', 'payment_date', 'targeted_months', 'paid_amount', 'remaining_balance'],
            order_by: 'payment_date desc', // الأحدث فوق
            limit_page_length: 0
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                let rows = '';
                r.message.forEach((rec) => {
                    rows += `
                        <tr>
                            <td style="text-align:center;">${frappe.datetime.str_to_user(rec.payment_date)}</td>
                            <td>${rec.receipt_book || ''}</td>
                            <td style="text-align:center;">${rec.paper_receipt_no || ''}</td>
                            <td>${rec.targeted_months || ''}</td>
                            <td style="text-align:left;">${format_currency(rec.paid_amount)}</td>
                            <td style="text-align:left; color:#d9534f;">${format_currency(rec.remaining_balance)}</td>
                            <td style="text-align:center;">
                                <a href="/app/quran-receipt/${rec.name}" target="_blank" class="btn btn-xs btn-default">عرض</a>
                            </td>
                        </tr>
                    `;
                });

                let table_html = `
                    <div class="table-responsive" style="max-height: 300px; overflow-y: auto; border: 1px solid #d1d8dd; border-radius: 6px;">
                        <table class="table table-bordered table-hover" style="margin-bottom: 0;">
                            <thead style="background: #f4f5f7; position: sticky; top: 0; z-index: 1;">
                                <tr>
                                    <th style="text-align:center;">التاريخ</th>
                                    <th>رقم الدفتر</th>
                                    <th style="text-align:center;">رقم الإيصال</th>
                                    <th>الفترة المستهدفة</th>
                                    <th>المدفوع</th>
                                    <th>المتبقي</th>
                                    <th style="text-align:center;">الإجراء</th>
                                </tr>
                            </thead>
                            <tbody>${rows}</tbody>
                        </table>
                    </div>
                `;
                html_field.html(table_html);
            } else {
                html_field.html('<div style="text-align:center; padding:20px; color:#888;">لا توجد إيصالات مسجلة لهذا الطالب (أو في هذا العام الدراسي).</div>');
            }
        }
    });
}

frappe.ui.form.on('Quran Settings', {
    refresh: function(frm) {
        if (!frm.is_new()) {
            frm.add_custom_button(__('🔄 ترحيل الأرصدة للفترة الجديدة'), function() {
                frappe.confirm(
                    'هل أنت متأكد من ترحيل الأرصدة؟<br>سيتم نقل (متبقي الفترة القديمة) إلى (الرصيد السابق)، وبدء فترة جديدة لجميع الطلاب النشطين.',
                    function() {
                        // تجميد الشاشة
                        frappe.dom.freeze('جاري ترحيل الأرصدة... يرجى الانتظار');

                        frappe.call({
                            method: 'rollover_student_balances',
                            callback: function(r) {
                                // لو السيرفر رجع رسالة، بنعرضها
                                if (r.message) {
                                    frappe.msgprint({
                                        title: 'عملية ناجحة',
                                        indicator: 'green',
                                        message: r.message
                                    });
                                }
                            },
                            // always بتتنفذ سواء السيرفر نجح أو فشل
                            always: function() {
                                frappe.dom.unfreeze(); 
                            }
                        });
                    }
                );
            }, __('إجراءات متقدمة'));
        }
    }
});

frappe.ui.form.on('Student', {
    setup: function(frm) {
        // فلترة المجموعات بناءً على الفرع
        frm.set_query('custom_student_group', function() {
            return {
                filters: {
                    custom_branch: frm.doc.custom_branch
                }
            };
        });
    }, 


    // 1. أول ما الصفحة تفتح (عشان لو حقل الاشتراك اتجاب أوتوماتيك من المجموعة)
    onload: function(frm) {
        if (frm.is_new()) {
            set_initial_remaining(frm);
        }
    },

    // 2. لو غيرنا المجموعة أو حقل الاشتراك اتغير (وبنعمل طالب جديد)
    custom_current_period_fee: function(frm) {
        if (frm.is_new()) {
            frm.set_value('custom_current_remaining', frm.doc.custom_current_period_fee || 0);
            calculate_total_remaining(frm);
        }
    },

    // 3. الحسابات اليدوية زي ما هي
    custom_previous_balance: function(frm) {
        calculate_total_remaining(frm);
    },

    custom_current_remaining: function(frm) {
        calculate_total_remaining(frm);
    }
});

// دالة: لو طالب جديد، نخلي المتبقي = الاشتراك
function set_initial_remaining(frm) {
    // لو الحقل فاضي أو بصفر، وفيه اشتراك متسجل
    if ((!frm.doc.custom_current_remaining || frm.doc.custom_current_remaining == 0) && frm.doc.custom_current_period_fee > 0) {
        frm.set_value('custom_current_remaining', frm.doc.custom_current_period_fee);
        calculate_total_remaining(frm);
    }
}

// دالة: حساب الإجمالي
function calculate_total_remaining(frm) {
    let prev_bal = frm.doc.custom_previous_balance || 0;
    let curr_rem = frm.doc.custom_current_remaining || 0;

    let total = prev_bal + curr_rem;
    frm.set_value('custom_total_remaining', total);
}

frappe.ui.form.on('Quran Receipt', {
    // أول ما تختار الدفتر
    receipt_book: function(frm) {
        // لو المستند جديد واخترنا دفتر
        if (frm.is_new() && frm.doc.receipt_book) {
            get_next_receipt_number(frm);
        }
    }
});

function get_next_receipt_number(frm) {
    // بنجيب بيانات الدفتر عشان نعرف رقم البداية
    frappe.db.get_doc('Quran Receipt Book', frm.doc.receipt_book).then(book => {
        let start_no = book.start_receipt_no || 1;

        // بنجيب كل الإيصالات اللي في الدفتر ده
        frappe.db.get_list('Quran Receipt', {
            filters: { receipt_book: frm.doc.receipt_book },
            fields: ['paper_receipt_no'],
            limit: 0
        }).then(res => {
            let next_no = start_no;

            if (res && res.length > 0) {
                // بنحول الأرقام لأرقام صحيحة ونتجاهل أي حروف
                let numbers = res.map(r => parseInt(r.paper_receipt_no)).filter(n => !isNaN(n));
                if (numbers.length > 0) {
                    let max_no = Math.max(...numbers); // بنجيب أكبر رقم
                    if (max_no >= next_no) {
                        next_no = max_no + 1; // نزود عليه 1
                    }
                }
            }

            // بنحط الرقم الجديد في الخانة
            frm.set_value('paper_receipt_no', next_no);

            // رسالة صغيرة تظهر للمستخدم تطمنه
            frappe.show_alert({
                message: `تم اقتراح رقم الإيصال التالي: ${next_no}`,
                indicator: 'blue'
            }, 5);
        });
    });
}

frappe.ui.form.on('Student Group', {
    onload: function(frm) {
        // 🌟 أول ما الصفحة تفتح، لو الفورم جديد، بنمسح الحقل فوراً
        if (frm.is_new() && frm.fields_dict.custom_students_cards_html) {
            frm.fields_dict.custom_students_cards_html.$wrapper.empty();
        }
    },

    refresh: function(frm) {
        if (frm.is_new()) {
            // تأكيد إضافي لو الفورم جديد
            if (frm.fields_dict.custom_students_cards_html) {
                frm.fields_dict.custom_students_cards_html.$wrapper.empty();
            }
        } else {
            // لو الفورم محفوظ، بنعرض الكروت
            render_student_cards(frm);
        }
    }
});

function render_student_cards(frm) {
    let wrapper = frm.fields_dict.custom_students_cards_html.$wrapper;
    wrapper.html('<div style="text-align:center; padding: 20px;">جاري تحميل الطلاب...</div>');

    frappe.db.get_list('Student', {
        filters: { custom_student_group: frm.doc.name },
        fields: ['name', 'student_name', 'custom_student_code', 'custom_status', 'student_mobile_number'],
        limit: 0
    }).then(students => {
        if (!students || students.length === 0) {
            wrapper.html('<div class="alert alert-warning" style="text-align:center;">لا يوجد طلاب في هذه المجموعة حالياً.</div>');
            return;
        }

        let cards_html = '<div class="row" style="display: flex; flex-wrap: wrap; gap: 15px; margin: 0;">';

        students.forEach(s => {
            let status_color = s.custom_status === 'موجود' ? '#333333' : '#dc3545'; 
            let status_icon = s.custom_status === 'موجود' ? 'fa-check-circle' : 'fa-times-circle';

            cards_html += `
                <div class="col-sm-6 col-md-4" style="padding: 0;">
                    <div class="card" style="border-top: 4px solid ${status_color}; box-shadow: 0 2px 5px rgba(0,0,0,0.1);">
                        <div class="card-body" style="padding: 15px;">
                            <h5 class="card-title" style="font-weight: bold; margin-bottom: 5px;">
                                <a href="/app/student/${s.name}" target="_blank">${s.student_name}</a>
                            </h5>
                            <h6 class="card-subtitle mb-2 text-muted">كود: ${s.custom_student_code || 'غير مسجل'}</h6>

                            <p class="card-text" style="margin-bottom: 5px; font-size: 13px;">
                                <i class="fa fa-phone"></i> ${s.student_mobile_number || 'لا يوجد رقم'}
                            </p>

                            <span class="badge" style="background-color: ${status_color}; color: white; padding: 5px 10px;">
                                <i class="fa ${status_icon}"></i> ${s.custom_status || 'غير محدد'}
                            </span>
                        </div>
                    </div>
                </div>
            `;
        });
        cards_html += '</div>';

        wrapper.html(cards_html);
    });
}

