    let buttons_html = `
        <div style="display: flex; gap: 10px; margin-bottom: 15px; margin-top: 5px; flex-wrap: wrap;">
            <button class="btn btn-primary btn-sm print-btn" id="btn-print-attendance" style="background-color: #17a2b8; border-color: #17a2b8; color: white; font-weight: bold; font-size: 13px; padding: 6px 15px;">
                <i class="fa fa-calendar-check-o"></i> كشف الحضور والغياب
            </button>

            <button class="btn btn-primary btn-sm print-btn" id="btn-print-quran" style="background-color: #28a745; border-color: #28a745; color: white; font-weight: bold; font-size: 13px; padding: 6px 15px;">
                <i class="fa fa-book"></i> استمارة رصد القرآن
            </button>

            <button class="btn btn-primary btn-sm print-btn" id="btn-print-curriculum" style="background-color: #ffc107; border-color: #ffc107; color: #333; font-weight: bold; font-size: 13px; padding: 6px 15px;">
