    let wrapper = frm.fields_dict.custom_print_buttons_html.$wrapper;
    wrapper.html(buttons_html);

    // 3. ربط الأزرار بدوال الطباعة
    wrapper.find('#btn-print-attendance').on('click', function() {
        frappe.utils.print(frm.doc.doctype, frm.doc.name, 'Attendance Sheet', 'A4', 'Landscape');
